const fs=require('fs');
const vm=require('vm');
const html=fs.readFileSync('index.html','utf8');
let script=html.match(/<script>\\n([\\s\\S]*?)\\n  <\\/script>/)[1];
script=script.replace(/const ready=initThree\\(\\); bindEvents\\(\\); reset\\(sim\\.seed\\); if\\(ready\\)\\{cameraMode=\"cinematic\";animate\\(performance\\.now\\(\\)\\);\\} setTimeout\\(\\(\\)=>\\{runSelfTest\\(\\);\\},320\\);/, 'bindEvents(); reset(sim.seed);');
class Vector3 {
  constructor(x=0,y=0,z=0){this.x=x;this.y=y;this.z=z;}
  set(x=0,y=0,z=0){this.x=x;this.y=y;this.z=z;return this;}
  setScalar(v){this.x=v;this.y=v;this.z=v;return this;}
  clone(){return new Vector3(this.x,this.y,this.z)}
  copy(v){this.x=v.x;this.y=v.y;this.z=v.z;return this}
  add(v){this.x+=v.x;this.y+=v.y;this.z+=v.z;return this}
  addScaledVector(v,s){this.x+=v.x*s;this.y+=v.y*s;this.z+=v.z*s;return this}
  sub(v){this.x-=v.x;this.y-=v.y;this.z-=v.z;return this}
  multiplyScalar(s){this.x*=s;this.y*=s;this.z*=s;return this}
  lengthSq(){return this.x*this.x+this.y*this.y+this.z*this.z}
  length(){return Math.sqrt(this.lengthSq())}
  normalize(){const l=this.length();return l?this.multiplyScalar(1/l):this}
  dot(v){return this.x*v.x+this.y*v.y+this.z*v.z}
  clampLength(min,max){const l=this.length(); if(l>max)this.multiplyScalar(max/l); else if(l<min&&l>1e-12)this.multiplyScalar(min/l); return this}
  lerp(v,a){this.x+=(v.x-this.x)*a;this.y+=(v.y-this.y)*a;this.z+=(v.z-this.z)*a;return this}
  getComponent(i){return [this.x,this.y,this.z][i]}
  setComponent(i,v){if(i===0)this.x=v;if(i===1)this.y=v;if(i===2)this.z=v;return this}
  reflect(n){const d=2*this.dot(n);return this.sub(n.clone().multiplyScalar(d))}
}
class Euler { constructor(x=0,y=0,z=0){this.x=x;this.y=y;this.z=z;} }
class Quaternion {
  constructor(x=0,y=0,z=0,w=1){this.x=x;this.y=y;this.z=z;this.w=w;}
  set(x,y,z,w){this.x=x;this.y=y;this.z=z;this.w=w;return this}
  identity(){return this.set(0,0,0,1)}
  clone(){return new Quaternion(this.x,this.y,this.z,this.w)}
  copy(q){return this.set(q.x,q.y,q.z,q.w)}
  normalize(){const l=Math.hypot(this.x,this.y,this.z,this.w)||1;this.x/=l;this.y/=l;this.z/=l;this.w/=l;return this}
  invert(){const n=this.x*this.x+this.y*this.y+this.z*this.z+this.w*this.w||1;this.x=-this.x/n;this.y=-this.y/n;this.z=-this.z/n;this.w=this.w/n;return this}
  multiply(q){const ax=this.x,ay=this.y,az=this.z,aw=this.w,bx=q.x,by=q.y,bz=q.z,bw=q.w;this.x=ax*bw+aw*bx+ay*bz-az*by;this.y=ay*bw+aw*by+az*bx-ax*bz;this.z=az*bw+aw*bz+ax*by-ay*bx;this.w=aw*bw-ax*bx-ay*by-az*bz;return this}
